def stiff_forward(t, y):
    return np.array([-1000*(y[0] - np.cos(t)) - np.sin(t), -0.5*y[1]])
def stiff_forward_jac(t, y): return np.array([[-1000.,0.],[0.,-0.5]])
def stiff_backward(t, y):
    return np.array([1000*(y[0] - np.cos(t)) - np.sin(t), 0.5*y[1]])
def stiff_backward_jac(t, y): return np.array([[1000.,0.],[0.,0.5]])
